#include <stdio.h>
int main(void) {
    int a[4] = {5, 1, 4, 2};
    for (int j = 0; j < 3; j++)
        if (a[j] > a[j+1]) { int t = a[j]; a[j] = a[j+1]; a[j+1] = t; }
    printf("%d %d %d %d\n", a[0], a[1], a[2], a[3]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[3] = {3, 1, 2};
    for (int i = 1; i < 3; i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) { a[j+1] = a[j]; j--; }
        a[j+1] = key;
    }
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[3] = {3, 1, 2}, sw = 0, t;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2 - i; j++)
            if (a[j] > a[j+1]) { t = a[j]; a[j] = a[j+1]; a[j+1] = t; sw++; }
    printf("%d\n", sw);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {5, 4, 3, 2, 1}, sh = 0;
    for (int i = 1; i < 5; i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) { a[j+1] = a[j]; j--; sh++; }
        a[j+1] = key;
    }
    printf("%d\n", sh);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[4] = {1, 2, 4, 3}, sw, t;
    for (int i = 0; i < 3; i++) {
        sw = 0;
        for (int j = 0; j < 3 - i; j++)
            if (a[j] > a[j+1]) { t = a[j]; a[j] = a[j+1]; a[j+1] = t; sw = 1; }
        if (!sw) break;
    }
    printf("%d %d %d %d\n", a[0], a[1], a[2], a[3]);
    return 0;
}

